/// Main error type for AgentScribe
#[derive(Error, Debug)]
pub enum AgentScribeError {
    /// Configuration errors
    #[error("Configuration error: {0}")]
    Config(String),

    /// Plugin errors
    #[error("Plugin error in '{name}': {message}")]
    Plugin { name: String, message: String },

    /// Parser errors - these are logged but skipped during parsing
    #[error("{message}")]
    Parse {
        file: String,
        line: Option<usize>,
        message: String,
    },

    /// I/O errors
    #[error("I/O error: {0}")]
    Io(#[from] std::io::Error),

    /// JSON parsing errors
    #[error("JSON error: {0}")]
    Json(#[from] serde_json::Error),

    /// TOML parsing errors
    #[error("TOML error: {0}")]
    Toml(#[from] toml::de::Error),

    /// Glob pattern errors
    #[error("Glob pattern error: {0}")]
    Glob(String),

    /// Timestamp parsing errors
    #[error("Timestamp parse error: {0}")]
    Timestamp(String),

    /// Invalid plugin definition
    #[error("Invalid plugin: {0}")]
    InvalidPlugin(String),

    /// File not found
    #[error("File not found: {0}")]
    FileNotFound(PathBuf),

    /// Data directory error
    #[error("Data directory error: {0}")]
    DataDir(String),

    /// State file errors
    #[error("State file error: {0}")]
    State(String),

    /// SQLite database errors
    #[error("SQLite error: {0}")]
    Sqlite(#[from] rusqlite::Error),

    /// Rules extraction errors
    #[error("Rules error: {0}")]
    Rules(String),

    /// Project registry errors
    #[error("Projects error: {0}")]
    Projects(String),

    /// Transcription errors
    #[error("Transcription error: {0}")]
    Transcription(String),

    /// Redaction errors
    #[error("Redaction error: {0}")]
    Redaction(String),

    /// Vector index errors
    #[error("Vector index error: {0}")]
    VectorIndex(String),

    /// Reflection export errors
    #[error("Reflection error: {0}")]
    Reflection(String),
}
```

